      let width = 0;

      function getBrowserWidth() {
        if (window.innerWidth) {
          width = window.innerWidth;
        }
        else if (document.documentElement &&
                document.documentElement.clientWidth !== 0) {
          width = document.documentElement.clientWidth;
        }
        else if (document.body) {
          width = document.body.clientWidth;
        }
      }

      function setWidth() {
        var vsp_url = "SOR?form=6&typ=vsp&page=1&sz=" + width;
        var nco_url = "SOR?form=6&typ=noncomp&page=1&sz=" + width;
        var pend_url = "SOR?form=6&typ=pending&page=1&sz=" + width;

        document.getElementById('VSP_link').href = vsp_url;
        document.getElementById('NCO_link').href = nco_url;
        document.getElementById('PEND_link').href = pend_url;
      }
     
   
   
     
   
     
