      document.querySelector('[data-open-slider]').addEventListener('click', function() {
        openNav();
      });

      document.querySelector('[data-close-slider]').addEventListener('click', function() {
        closeNav();
      });

      function openNav() {
        var open = document.getElementById('openButton');
        var close = document.getElementById('closeButton');
        open.classList.add("d-none");
        close.classList.remove("d-none");
        var sideNav =  document.getElementById("mySidenav");
        sideNav.style.width = "75%";
        sideNav.style.overflowY = "scroll";
      }

      function closeNav() {
        var open = document.getElementById('openButton');
        var close = document.getElementById('closeButton');
        open.classList.remove("d-none");
        close.classList.add("d-none");
        var sideNav =  document.getElementById("mySidenav");
        sideNav.style.width = "0";
        sideNav.style.overflowY = "hidden";
      }
     

   
 

     
       
         
           
             
             

           
         
       
       
         
           
             
               
                 
                   

                   
